local config = {
  ui_story_31150401_1_dialog_content = "I'm sorry for calling you here like this all of a sudden.",
  ui_story_31150401_2_dialog_content = "There's no need to be so formal, Naroxel.",
  ui_story_31150401_3_dialog_content = "Thank you, Navigator. I've looked around all the Colossus rooms over the past few days.",
  ui_story_31150401_4_dialog_content = "I see that you've managed to keep the interior of the Colossus very clean and tidy.",
  ui_story_31150401_5_dialog_content = "It just seems to lack that certain... essence of nature.",
  ui_story_31150401_6_dialog_content = "Essence of nature...? Do we really need anything like that on the Colossus?",
  ui_story_31150401_7_dialog_content = "Of course. A touch of natural vitality can work wonders on one's constitution.",
  ui_story_31150401_8_dialog_content = "Do you often feel tired but can't seem to sleep, Navigator?",
  ui_story_31150401_9_dialog_content = "All the time!",
  ui_story_31150401_10_dialog_content = "Do you sometimes feel upset for no reason at all, or find yourself burdened with headaches that just seem to come out of the blue?",
  ui_story_31150401_11_dialog_content = "Yeah, I can think of several instances...",
  ui_story_31150401_12_dialog_content = "All creatures of this the world are born from nature.",
  ui_story_31150401_13_dialog_content = "Without the nourishing presence of natural air, one's body is prone to such ailments.",
  ui_story_31150401_14_dialog_content = "Is it really that serious...!? What should I do!?",
  ui_story_31150401_15_dialog_content = "Worry not—I brought some plants here with me. They're guaranteed to create a more natural atmosphere on the Colossus.",
  ui_story_31150401_16_dialog_content = "Please come and have a look.",
  ui_story_31150401_17_dialog_content = "Wow... The unique atmosphere hit me as soon as I walked in...",
  ui_story_31150401_18_dialog_content = "There are so many plants in this room, Naroxel!",
  ui_story_31150401_19_dialog_content = "That's right.",
  ui_story_31150401_20_dialog_content = "Can you feel the fresh air soothing your lungs?",
  ui_story_31150401_21_dialog_content = "I can!",
  ui_story_31150401_22_dialog_content = "Do you feel euphoric and refreshed?",
  ui_story_31150401_23_dialog_content = "Yes! Yes, I do!",
  ui_story_31150401_24_dialog_content = "This is the power of nature.",
  ui_story_31150401_25_dialog_content = "I see...",
  ui_story_31150401_26_option_content = "Thank you for bringing nature to the Colossus.",
  ui_story_31150401_27_dialog_content = "There is no need to thank me. It's only natural.",
  ui_story_31150401_28_dialog_content = "It's great having you here, Naroxel. Maybe one day, we can transform the Colossus into a place like Eraveil...",
  ui_story_31150401_29_option_content = "Is it really that miraculous?",
  ui_story_31150401_30_dialog_content = "Have you never experienced anything similar while exploring outside the Colossus?",
  ui_story_31150401_31_dialog_content = "You must have noticed the difference between a dry, stifling town and a humid, invigorating forest?",
  ui_story_31150401_32_dialog_content = "It's true. I am ashamed to admit it, but although I'm a Caelestite, my understanding of nature...",
  ui_story_31150401_33_dialog_content = "Ah!",
  ui_story_31150401_34_dialog_content = "Be careful! Sorry, I forgot to mention that there are several cactus plants here.",
  ui_story_31150401_35_dialog_content = "Did one of them prick you?",
  ui_story_31150401_36_dialog_content = "It's all right. I just bumped into it.",
  ui_story_31150401_37_dialog_content = "I've seen these plants a few times in the Rediesel Desert, but I didn't realize you could get them in pots, too.",
  ui_story_31150401_38_dialog_content = "I chose them specifically.",
  ui_story_31150401_39_dialog_content = "Some people can't stand cacti, but I think they're quite charming.",
  ui_story_31150401_40_dialog_content = "I believe their sharp thorns actually serve to protect their soft hearts.",
  ui_story_31150401_41_dialog_content = "And unlike other plants, cacti emit their natural essence at night.",
  ui_story_31150401_42_dialog_content = "By placing cacti with other plants, we can enjoy the scent of nature all day long.",
  ui_story_31150401_43_dialog_content = "So, if I place a cactus in my room, I'll finally be able to sleep better...",
  ui_story_31150401_44_dialog_content = "Indeed. That's exactly right.",
  ui_story_31150401_45_dialog_content = "Well... Can I take one and put it in my room, then?",
  ui_story_31150401_46_dialog_content = "Of course you can, but you must take good care of it.",
  ui_story_31150401_47_dialog_content = "I will!",
  ui_story_31150401_48_dialog_content = "<color=#e8d9bb>A few days later.</color>",
  ui_story_31150401_49_dialog_content = "Hmm... It seems to be coming from the Navigator's room.",
  ui_story_31150401_50_dialog_content = "<color=#e8d9bb>Knock, knock.</color>",
  ui_story_31150401_51_dialog_content = "Naroxel... Is something wrong?",
  ui_story_31150401_52_dialog_content = "There seems to be a... distress signal coming from your room.",
  ui_story_31150401_53_dialog_content = "So, I thought I'd come and see what the matter is.",
  ui_story_31150401_54_dialog_content = "A distress signal? But I'm fine, and I haven't sent any kind of signal...",
  ui_story_31150401_55_dialog_content = "If it's not too much of an inconvenience, could I possibly come in and take a look?",
  ui_story_31150401_56_option_content = "Sure.",
  ui_story_31150401_57_dialog_content = "Thank you very much. Now, let's see...",
  ui_story_31150401_58_option_content = "Erm...",
  ui_story_31150401_59_dialog_content = "Worry not, I merely wish to confirm the source of the signal.",
  ui_story_31150401_60_dialog_content = "... Come in.",
  ui_story_31150401_61_dialog_content = "Yes, the signal is getting stronger. It's coming from...",
  ui_story_31150401_62_dialog_content = "From here!",
  ui_story_31150401_63_dialog_content = "The cactus is sending out a distress signal?",
  ui_story_31150401_64_dialog_content = "Yes. This cactus is dying... We must find a way to save it at once!",
  ui_story_31150401_65_dialog_content = "We mustn't delay—do you have a shovel and some scissors?",
  ui_story_31150401_66_dialog_content = "... I'll go find some!",
  ui_story_31150401_67_dialog_content = "What should I do now?",
  ui_story_31150401_68_dialog_content = "Wait.",
  ui_story_31150401_69_dialog_content = "Just... wait?",
  ui_story_31150401_70_dialog_content = "I removed a rotten segment of the cactus' roots, just now.",
  ui_story_31150401_71_dialog_content = "Now, we need to wait for nature to summon the wind and sunshine to dry the soil in the flowerpot.",
  ui_story_31150401_72_dialog_content = "Then, when the soil dries out, can I put the cactus back in the flowerpot?",
  ui_story_31150401_73_dialog_content = "Correct.",
  ui_story_31150401_74_dialog_content = "Okay, let me make a note. How did this even happen?",
  ui_story_31150401_75_dialog_content = "Also, you said you heard the cactus' distress signal just now, but... how?",
  ui_story_31150401_76_dialog_content = "In my opinion, although plants do not possess the same intelligence as we Aurorians and Caelestites...",
  ui_story_31150401_77_dialog_content = "But they also age, wither, and die—as well as respond to external stimuli.",
  ui_story_31150401_78_dialog_content = "Plants have their own way of expressing themselves.",
  ui_story_31150401_79_dialog_content = "I'm just a little more sensitive to them than most, so I can detect the pheromones they release.",
  ui_story_31150401_80_dialog_content = "You're just a little more sensitive...?",
  ui_story_31150401_81_dialog_content = "I thought you might be able to sense these signals, too—using your Caelestite psychic abilities, of course.",
  ui_story_31150401_82_dialog_content = "I'm not very good at using my abilities on plants yet...",
  ui_story_31150401_83_dialog_content = "Worry not. Even if you cannot sense their thoughts, you can understand their needs if you observe them carefully enough.",
  ui_story_31150401_84_dialog_content = "Take this cactus, for example. As you know, it originally lived in the desert.",
  ui_story_31150401_85_dialog_content = "How did you feel when you went to the desert?",
  ui_story_31150401_86_option_content = "I felt... thirsty?",
  ui_story_31150401_87_dialog_content = "That's right. And the plants there feel the same way.",
  ui_story_31150401_88_option_content = "I felt tired.",
  ui_story_31150401_89_dialog_content = "It's really very difficult living in the desert, due to the hot weather and general scarcity of water.",
  ui_story_31150401_90_dialog_content = "Cacti have succeeded in adapting to life in the desert.",
  ui_story_31150401_91_dialog_content = "To reduce the amount of water they lose, they grow sharp, thin thorns.",
  ui_story_31150401_92_dialog_content = "To store more water, they grow strong, sturdy stems.",
  ui_story_31150401_93_dialog_content = "And thus, we can say that the cactus has adapted perfectly to its environment.",
  ui_story_31150401_94_dialog_content = "Adapted perfectly to its environment...",
  ui_story_31150401_95_dialog_content = "So, you mean, cacti don't need too much water?",
  ui_story_31150401_96_dialog_content = "Yes. Aren't they remarkably resilient?",
  ui_story_31150401_97_dialog_content = "I thought giving it lots of water and nourishment was the best way to take care of it...",
  ui_story_31150401_98_dialog_content = "I watered it every morning and evening... But it looks like I was causing it harm...",
  ui_story_31150401_99_dialog_content = "Well, sometimes, if you don't understand the needs of those around you, there is a chance you may inadvertently cause more harm than good...",
  ui_story_31150401_100_dialog_content = "This particular situation is not very serious, so there's no need to blame yourself too much...",
  ui_story_31150401_101_dialog_content = "Can you show me the right way to take care of it, Naroxel?",
  ui_story_31150401_102_dialog_content = "I promise to take good care of it this time!",
  ui_story_31150401_103_dialog_content = "Certainly. It's quite moving to see such determination.",
  ui_story_31150401_104_dialog_content = "Nature will certainly come to you and show you the way.",
  ui_story_31150401_105_dialog_content = "Maybe it's time I give it to you...",
  ui_story_31150401_106_dialog_content = "Huh? What do you mean?",
  ui_story_31150401_107_dialog_content = "Oh, don't mind me. I was just talking to myself.",
  ui_story_31150401_108_dialog_content = "Now, allow me to tell you how to take care of this cactus.",
  ui_story_31150401_109_dialog_content = "I'm all ears!",
  ui_story_31150401_110_dialog_content = "Navigator, I'm back to disturb you, once again.",
  ui_story_31150401_111_dialog_content = "Naroxel, you're not here to see if I've been taking good care of the cactus, are you?",
  ui_story_31150401_112_dialog_content = "Well, now that you mention it, a tiny peek wouldn't hurt.",
  ui_story_31150401_113_dialog_content = "But I can already sense, even from standing here at the door, that the cactus has fully recovered.",
  ui_story_31150401_114_dialog_content = "Really? I've been worrying about it non-stop recently. I was afraid I might harm it again...",
  ui_story_31150401_115_dialog_content = "Well, I'm glad to say that there are no withered or rotten patches to speak of.",
  ui_story_31150401_116_dialog_content = "So... What kind of pheromone is the cactus emitting now?",
  ui_story_31150401_117_dialog_content = "Do you really wish to know, Navigator?",
  ui_story_31150401_118_dialog_content = "I think I do... I don't know why, but recently, this cactus has me constantly thinking of the Rediesel Wrench...",
  ui_story_31150401_119_dialog_content = "I was worried that a cactus from the desert might be as short-tempered as those guys...",
  ui_story_31150401_120_dialog_content = "Your concern is not an unreasonable one. After all, environment plays a significant part in one's development.",
  ui_story_31150401_121_dialog_content = "At this current moment, the cactus is... complaining that you almost killed it.",
  ui_story_31150401_122_dialog_content = "...!",
  ui_story_31150401_123_dialog_content = "Haha, I jest, I jest.",
  ui_story_31150401_124_dialog_content = "Worry not, Navigator. I can now sense that it is releasing pleasant pheromones.",
  ui_story_31150401_125_dialog_content = "I really wasn't expecting you to make a joke like that...",
  ui_story_31150401_126_dialog_content = "Here's something else you were not expecting.",
  ui_story_31150401_127_dialog_content = "Is this... a new potted plant—for me?",
  ui_story_31150401_128_dialog_content = "If you can correctly tell me how to take care of this plant, I'll give it to you.",
  ui_story_31150401_129_dialog_content = "No problem!",
  ui_story_31150401_130_dialog_content = "Hmm... From the look of it, I'd say it's the type of plant that needs to be watered regularly, right?",
  ui_story_31150401_131_dialog_content = "Because its leaves are completely different from the ones on the cactus... I guess... I should try to keep the soil moist.",
  ui_story_31150401_132_dialog_content = "Right now, it seems to be in... is this called the flowering phase? So, I may need to add some fertilizer...",
  ui_story_31150401_133_dialog_content = "Basically, I think I'll have to experiment a little before I know for sure.",
  ui_story_31150401_134_dialog_content = "Well, I believe you have learned to understand this plant's demands purely through the art of observation.",
  ui_story_31150401_135_dialog_content = "This is for you. From it, I hope you gain something you truly cherish.",
  ui_story_31150401_136_dialog_content = "Thank you. I'll take good care of it!",
  ui_story_31150401_137_dialog_content = "But... What kind of flower is this?",
  ui_story_31150401_138_dialog_content = "Naroxel's already left...",
  ui_story_31150401_139_dialog_content = "Worry not! Even if I don't know your name, I'll give you a pleasant environment!",
  ui_story_31150401_140_dialog_content = "<color=#e8d9bb>A few days later.</color>",
  ui_story_31150401_141_dialog_content = "That's strange... I can suddenly sense... happiness in the air.",
  ui_story_31150401_142_dialog_content = "Anyway... Little friend, how much water would you like to drink today?",
  ui_story_31150401_143_dialog_content = "Huh...? What is that white fluffy stuff?",
  ui_story_31150401_144_dialog_content = "It's a dandelion!",
  ui_story_31150401_145_dialog_content = "I've seen this before, in an image from the past. These plants once grew in Eraveil...",
  ui_story_31150401_146_dialog_content = "I hope you gain something you truly cherish.",
  ui_story_31150401_147_dialog_content = "Naroxel...",
  ui_story_31150401_148_dialog_content = "Thank you.",
  ui_story_31150601_1_dialog_content = "The smell of the salty sea breeze...",
  ui_story_31150601_2_dialog_content = "And the sunshine today is really nice.",
  ui_story_31150601_3_dialog_content = "It feels like it's been so long since I last went on a vacation from all my worries...",
  ui_story_31150601_4_dialog_content = "Naroxel?",
  ui_story_31150601_5_dialog_content = "PlayerName?",
  ui_story_31150601_6_dialog_content = "I didn't expect to see you here.",
  ui_story_31150601_7_dialog_content = "Am I interrupting your vacation?",
  ui_story_31150601_8_dialog_content = "Of course not, I'm just surprised to see you.",
  ui_story_31150601_9_dialog_content = "I was just lamenting the fact that I had no one to talk to.",
  ui_story_31150601_10_dialog_content = "I saw Bessie from the other side of the street just now.",
  ui_story_31150601_11_dialog_content = "Her antlers and physique really catch the eye—",
  ui_story_31150601_12_dialog_content = "I wouldn't have come over and found you if I hadn't seen her.",
  ui_story_31150601_13_dialog_content = "Oh, so that's how you found me.",
  ui_story_31150601_14_dialog_content = "The sea breeze around here is truly sublime.",
  ui_story_31150601_15_dialog_content = "Would you like to come over here and have some rest?",
  ui_story_31150601_16_dialog_content = "I'll just sit in this empty chair beside you.",
  ui_story_31150601_17_dialog_content = "Why did you decide to go on vacation all of a sudden?",
  ui_story_31150601_18_dialog_content = "Heheh, can't wrap your head around the idea of a workaholic suddenly choosing to take a break?",
  ui_story_31150601_19_dialog_content = "In order to satisfy the delivery needs of Lumopolis, the Courier Union has recently introduced some new freelancers.",
  ui_story_31150601_20_dialog_content = "I've been putting a lot of work into training them.",
  ui_story_31150601_21_dialog_content = "And one day, Wendy found me totally exhausted and collapsed at the union entrance.",
  ui_story_31150601_22_dialog_content = "So, Wendy strongly advised that I go on holiday, and so—",
  ui_story_31150601_23_dialog_content = "As you can see, I decided to come to the seaside to unwind for a while.",
  ui_story_31150601_24_dialog_content = "The way you always work so hard. It kinda makes me feel ashamed of myself.",
  ui_story_31150601_25_dialog_content = "Are you trying to flatter me?",
  ui_story_31150601_26_dialog_content = "In the eyes of those rookies, I'm nothing more than an old-fashioned fossil who's a stickler for the rules...",
  ui_story_31150601_27_dialog_content = "What happened?",
  ui_story_31150601_28_dialog_content = "You're a senior member of the Courier Union. I never would have thought rookies would dare be so rude.",
  ui_story_31150601_29_dialog_content = "Please don't blame them too harshly.",
  ui_story_31150601_30_dialog_content = "I believe that they might not be totally wrong...",
  ui_story_31150601_31_dialog_content = "<color=#e8d9bb>A month ago...</color>",
  ui_story_31150601_32_dialog_content = "That's all for our recent tasks.",
  ui_story_31150601_33_dialog_content = "Please pay attention to the sender's designated delivery time.",
  ui_story_31150601_34_dialog_content = "For urgent letters, it's necessary that you inform the sender of the fastest time possible.",
  ui_story_31150601_35_dialog_content = "Deliver within the agreed time. No extensions are allowed.",
  ui_story_31150601_36_dialog_content = "Sometimes the sender may have special requirements with regard to the delivery time, so please also pay attention to them.",
  ui_story_31150601_37_dialog_content = "If you still have any questions, you can come to the union and ask me at any time.",
  ui_story_31150601_38_dialog_content = "I have a question!",
  ui_story_31150601_39_dialog_content = "Go on.",
  ui_story_31150601_40_dialog_content = "We've been here for a month now and get all these delivery requests daily.",
  ui_story_31150601_41_dialog_content = "Is the Courier Union only capable of providing just these old-fashioned delivery services?!",
  ui_story_31150601_42_dialog_content = "If we carry on like this, we'll all be phased out eventually!",
  ui_story_31150601_43_dialog_content = "Phased out...? You mean...",
  ui_story_31150601_44_dialog_content = "It means outdated, and obsolete!",
  ui_story_31150601_45_dialog_content = "Many people nowadays no longer use the Courier Union anymore, those small post offices can also fulfill their needs.",
  ui_story_31150601_46_dialog_content = "Right. Last time I was on a delivery, the customer asked me if the Courier Union provides any other form of mailing service...",
  ui_story_31150601_47_dialog_content = "Yeah! I've had enough of this over the past month! The way we make deliveries feels like an old fossil. It doesn't belong in the modern world!",
  ui_story_31150601_48_dialog_content = "And Pepi said it's already quite difficult just to deliver the letters.",
  ui_story_31150601_49_dialog_content = "Exactly!",
  ui_story_31150601_50_dialog_content = "Because everyone in the Courier Union holds this idea, the union gradually loses its relevance!",
  ui_story_31150601_51_dialog_content = "Don't you agree, Lady Naroxel?",
  ui_story_31150601_52_dialog_content = "I'll consider all you've said carefully.",
  ui_story_31150601_53_dialog_content = "Well, then, in addition to the current delivery tasks, I'll arrange a new job for everyone—",
  ui_story_31150601_54_dialog_content = "When you have time, I hope you can all help to gather opinions from the public.",
  ui_story_31150601_55_dialog_content = "Compile everyone's experiences with the Courier Union's service and organize them into a book of user opinions.",
  ui_story_31150601_56_dialog_content = "I think we can leave things at that for today.",
  ui_story_31150601_57_dialog_content = "So that's what happened.",
  ui_story_31150601_58_dialog_content = "Hmm...",
  ui_story_31150601_59_dialog_content = "Do you also think... I'm an old fossil, with no place in the modern world?",
  ui_story_31150601_60_option_content = "I think you're a busy PERSON.",
  ui_story_31150601_61_dialog_content = "May I ask... what exactly you mean by that?",
  ui_story_31150601_62_dialog_content = "Well, because you're always so busy, you don't really have the time to do anything other than deliver letters.",
  ui_story_31150601_63_option_content = "Of course not!",
  ui_story_31150601_64_dialog_content = "When I really think about it, given all I know about you, I know you're someone who's willing to change with the times.",
  ui_story_31150601_65_dialog_content = "And a \"fossil\" is someone stubborn and unwilling to change, right?",
  ui_story_31150601_66_dialog_content = "I see... Thank you.",
  ui_story_31150601_67_dialog_content = "I think I need your advice.",
  ui_story_31150601_68_dialog_content = "In your eyes, delivering letters basically means delivering them on time, right?",
  ui_story_31150601_69_dialog_content = "That used to be the only consideration when it came to delivering letters—",
  ui_story_31150601_70_dialog_content = "But new possibilities have opened up.",
  ui_story_31150601_71_dialog_content = "I think those newcomers were there to remind you of this.",
  ui_story_31150601_72_dialog_content = "Yes... I read the customer opinions they collected carefully after that.",
  ui_story_31150601_73_dialog_content = "I'd never have guessed that the public had so many opinions about the union before that.",
  ui_story_31150601_74_dialog_content = "It's only because you're so immersed in your work that you overlook the possibility of future development.",
  ui_story_31150601_75_dialog_content = "That makes sense...",
  ui_story_31150601_76_dialog_content = "I should just take a step back once in a while, like Wendy said...",
  ui_story_31150601_77_dialog_content = "I'm suddenly reminded of my childhood in Northland.",
  ui_story_31150601_78_dialog_content = "The trestled pier in summer... it's so different from the scenery there.",
  ui_story_31150601_79_dialog_content = "I've been rushing to and fro, busying myself with work all this time, I haven't even really taken the time to have a good look at the blue sky above me.",
  ui_story_31150601_80_dialog_content = "I'm glad you've finally realized that!",
  ui_story_31150601_81_dialog_content = "Since we're all on vacation, let's not talk about work anymore. Let's just enjoy the fun of being by the sea!",
  ui_story_31150601_82_dialog_content = "How about we go play in the water?",
  ui_story_31150601_83_dialog_content = "Sure...",
  ui_story_31150601_84_dialog_content = "Um... the water's a bit chilly.",
  ui_story_31150601_85_dialog_content = "Well, I guess the hotter the weather, the cooler the sea feels.",
  ui_story_31150601_86_dialog_content = "The sensation of floating in the water is so relaxing.",
  ui_story_31150601_87_dialog_content = "Huh? What's this?",
  ui_story_31150601_88_dialog_content = "Is that a bottle?",
  ui_story_31150601_89_dialog_content = "There seems to be a message rolled up inside it.",
  ui_story_31150601_90_dialog_content = "Open it!",
  ui_story_31150601_91_dialog_content = "Should I?",
  ui_story_31150601_92_dialog_content = "Of course! It's a letter without a courier! That means anyone can read it!",
  ui_story_31150601_93_dialog_content = "Let's take a look...",
  ui_story_31150601_94_dialog_content = "\"Beautiful beautiful sea, please fulfill my birthday wish.\"",
  ui_story_31150601_95_dialog_content = "\"I hope Mom and Dad will be together forever and celebrate my birthday every year.\"",
  ui_story_31150601_96_dialog_content = "\"If things could just be like the way they are now... I'd be so happy, now and always.\"",
  ui_story_31150601_97_dialog_content = "\"Dear dear sea, if it's possible, I want to become a superstar too when I grow up...\"",
  ui_story_31150601_98_dialog_content = "Pfffff—",
  ui_story_31150601_99_dialog_content = "This little girl is very cute.",
  ui_story_31150601_100_dialog_content = "She wrote so many wishes. I wonder if any of them will come true.",
  ui_story_31150601_101_dialog_content = "Heheh, I'll be praying for her.",
  ui_story_31150601_102_dialog_content = "Indeed. The waves served as the courier of this letter...",
  ui_story_31150601_103_dialog_content = "This bottle has no recipient, as it only represents someone's wishes.",
  ui_story_31150601_104_dialog_content = "I see now...",
  ui_story_31150601_105_dialog_content = "The Courier Union can provide more services according to the needs of the people—",
  ui_story_31150601_106_dialog_content = "Like messages in a bottle.",
  ui_story_31150601_107_dialog_content = "Some mailing methods exist solely for the sake of fun.",
  ui_story_31150601_108_dialog_content = "The Courier Union can provide a message-in-a-bottle service without a fixed recipient for people far from the sea. It might turn out to be a hit.",
  ui_story_31150601_109_dialog_content = "Hmmm, and if we expand our thinking even further...",
  ui_story_31150601_110_dialog_content = "We can also institute scheduled mail delivery services, such as a service where you can send mail to your future self.",
  ui_story_31150601_111_dialog_content = "Oh! This is the kind of idea that could only come from the mind of an experienced courier! It's really interesting!",
  ui_story_31150601_112_dialog_content = "Delivering letters at different times will bring about a different experience.",
  ui_story_31150601_113_dialog_content = "I think we could probably also organize an anonymous pen pal match-up activity—",
  ui_story_31150601_114_dialog_content = "Even people with no letters to send can still find a reason to communicate with others through this kind of activity.",
  ui_story_31150601_115_dialog_content = "Relying on fate alone to bring complete strangers together. What a wonderful idea!",
  ui_story_31150601_116_dialog_content = "You've given me so many exciting ideas, PlayerName.",
  ui_story_31150601_117_dialog_content = "I'd like to thank you... for opening my mind.",
  ui_story_31150601_118_dialog_content = "I'll tell everyone about the new work arrangements as soon as I return home.",
  ui_story_31150601_119_dialog_content = "And now, I can enjoy the rest of my holiday without a care in the world!",
  ui_story_31150601_120_dialog_content = "Well, perhaps not...",
  ui_story_31150601_121_dialog_content = "Hmm?",
  ui_story_31150601_122_dialog_content = "<color=#e8d9bb>A blur of colorful feathers floats down to the sea's surface, as Olive, the spirit cuckoo's head becomes stuck in the bottle drifting on the waves.</color>",
  ui_story_31150601_123_dialog_content = "<size=45>Olive!!!</size>",
  ui_story_31150601_124_dialog_content = "Squawk!",
  ui_story_31150601_125_dialog_content = "You curious little bird... Can you understand what's written on that piece of paper?",
  ui_story_31150601_126_dialog_content = "Squawk—!!! Squawk!!!",
  ui_story_31150601_127_dialog_content = "Wait, let me help you..."
}
return config
